// ───────────── C shim (RP2) ─────────────
@location('Sources/CSlopDiskShim/include/CSlopDiskShim.h', 'Sources/CSlopDiskShim/shim.c')
// hint: 반환값은 0(성공) 또는 errno. 출력 인자의 C 타입은 ioctl이 요구하는 크기와 정확히 맞춘다(F11).
imagine int sd_get_logical_block_size(int fd, uint32_t *out) {
    requirements(`macOS: DKIOCGETBLOCKSIZE. Linux: BLKSSZGET(int로 받아 uint32_t로 변환).`);
}
imagine int sd_get_block_count(int fd, uint64_t *out) {
    requirements(`macOS: DKIOCGETBLOCKCOUNT. Linux: BLKGETSIZE64(바이트) / 논리 섹터 크기.`);
}
imagine int sd_synchronize_cache(int fd) {
    requirements(`macOS: DKIOCSYNCHRONIZECACHE. Linux: fsync. 그 밖의 플랫폼: ENOTSUP.`);
}

// ───────────── SDRawDevice ─────────────
@location('Sources/SlopDisk/Devices/SDRawDevice.swift')
imagine final class SDRawDevice: SDBlockDevice {
    enum Acknowledgement: Sendable { case dataLossRisk }        // R2

    init(path: String, acknowledging: Acknowledgement) throws(SDError)          // readWrite
    init(readOnlyPath path: String) throws(SDError)                             // RP1
    init(fileDescriptor fd: Int32, closeOnDeinit: Bool,
         acknowledging: Acknowledgement) throws(SDError)                         // RP3
    let path: String?                                                           // fd 주입이면 nil

    requirements(`
        경로 init은 open(O_RDWR 또는 O_RDONLY | O_CLOEXEC)으로 연 뒤 fstat으로 S_ISCHR/S_ISBLK를 확인한다(RP5).
        그 다음 flock(D26), sd_get_logical_block_size, sd_get_block_count 순서로 진행한다.
        fd init은 fcntl(F_GETFL)의 접근 모드로 isReadOnly를 정하고, closeOnDeinit이 true일 때만 flock을 건다(RP3).
        read/write는 RP4의 bounce buffer를 거쳐 pread/pwrite 루프를 돈다(짧은 I/O, EINTR 처리).
        synchronize는 sd_synchronize_cache를 부른다. ENOTTY/ENOTSUP이면 fsync로 폴백하고, 그래도 실패하면 .io.
        deinit은 소유한 fd만 close한다.
    `);
    ensure(`일반 파일 경로 → .invalidArgument`);
    ensure(`attach한 64 MiB 이미지의 /dev/rdiskN → sectorSize == 512, sectorCount == 131072`);
    ensure(`readOnlyPath로 연 디바이스에 write → .readOnly, 디바이스 바이트 불변`);
    ensure(`같은 rdiskN을 path init으로 두 번 열면 두 번째가 .locked`);
    ensure(`closeOnDeinit: false로 만든 인스턴스가 해제된 뒤에도 fcntl(fd, F_GETFD) != -1`);
}
